# situ capability map v1
# schema: ipv4.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.
#
# A struct's size is a bare number where it is fixed, `min..max` where
# it is bounded, and `min..` where nothing bounds it.

# codecs. `trusted` means the properties are declared and
# unverified: run `situc gen-codec-tests` to falsify a lying one.
codec internet_checksum derived expansion=+2 seekable=linear granularity=block systematic deterministic

struct ipv4_address size=4 atomic=NonAtomic
  ipv4_address.octets                    offset=AbsoluteStatic(0x00) size=Fixed(4) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic

struct ipv4_header size=20..60 mutate=Immutable repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.header                     offset=AbsoluteStatic(0x00) size=Bounded(20, 60) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting auth=Covered(header_checksum)
  ipv4_header.version                    offset=AbsoluteStatic(0x00) size=Fixed(4bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.ihl                        offset=AbsoluteStatic(0x00:4) size=Fixed(4bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.dscp                       offset=AbsoluteStatic(0x01) size=Fixed(6bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.ecn                        offset=AbsoluteStatic(0x01:6) size=Fixed(2bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.total_length               offset=AbsoluteStatic(0x02) size=Fixed(2) align=Aligned(2) repr=ValueConverted atomic=AtomicWord auth=Covered(header_checksum)
  ipv4_header.identification             offset=AbsoluteStatic(0x04) size=Fixed(2) align=Aligned(4) repr=ValueConverted atomic=AtomicWord auth=Covered(header_checksum)
  ipv4_header.<reserved0>                offset=AbsoluteStatic(0x06) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.dont_fragment              offset=AbsoluteStatic(0x06:1) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.more_fragments             offset=AbsoluteStatic(0x06:2) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.fragment_offset            offset=AbsoluteStatic(0x06:3) size=Fixed(13bit) align=Unaligned repr=ValueConverted atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.time_to_live               offset=AbsoluteStatic(0x08) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord auth=Covered(header_checksum)
  ipv4_header.protocol                   offset=AbsoluteStatic(0x09) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord auth=Covered(header_checksum)
  ipv4_header.header_checksum            offset=AbsoluteStatic(0x0A) size=Fixed(2) align=Aligned(2) repr=MemoryIdentical atomic=NonAtomic mutate=Immutable
  ipv4_header.source                     offset=AbsoluteStatic(0x0C) size=Fixed(4) align=Aligned(4) repr=MemoryIdentical atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.source.octets              offset=AbsoluteStatic(0x0C) size=Fixed(4) align=Aligned(4) repr=MemoryIdentical atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.destination                offset=AbsoluteStatic(0x10) size=Fixed(4) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.destination.octets         offset=AbsoluteStatic(0x10) size=Fixed(4) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic auth=Covered(header_checksum)
  ipv4_header.options                    offset=AbsoluteStatic(0x14) size=Bounded(0, 40) align=Aligned(4) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting auth=Covered(header_checksum)

struct ipv4_option size=1..255 mutate=Shifting atomic=NonAtomic
  ipv4_option.kind                       offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  ipv4_option.body                       offset=AbsoluteStatic(0x01) size=Bounded(0, 254) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
  ipv4_option.body.end_of_list           offset=AbsoluteStatic(0x01) size=Fixed(0) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic
  ipv4_option.body.no_operation          offset=AbsoluteStatic(0x01) size=Fixed(0) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic
  ipv4_option.body.sized                 offset=AbsoluteStatic(0x01) size=Bounded(1, 254) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
  ipv4_option.body.sized.length          offset=AbsoluteStatic(0x01) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord
  ipv4_option.body.sized.value           offset=AbsoluteStatic(0x02) size=Bounded(0, 253) align=Aligned(2) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting

struct nothing size=0

struct option_list size=0.. access=Sequential mutate=Shifting atomic=NonAtomic
  option_list.all                        offset=AbsoluteStatic(0x00) size=Unbounded align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic access=Sequential mutate=Shifting
  option_list.all[]                      offset=FrameStatic(0x00) size=Bounded(1, 255) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic access=Sequential mutate=Shifting
  option_list.all[].kind                 offset=FrameStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  option_list.all[].body                 offset=FrameStatic(0x01) size=Bounded(0, 254) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
  option_list.all[].body.end_of_list     offset=FrameStatic(0x01) size=Fixed(0) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic
  option_list.all[].body.no_operation    offset=FrameStatic(0x01) size=Fixed(0) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic
  option_list.all[].body.sized           offset=FrameStatic(0x01) size=Bounded(1, 254) align=Aligned(1) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
  option_list.all[].body.sized.length    offset=FrameStatic(0x01) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord
  option_list.all[].body.sized.value     offset=FrameStatic(0x02) size=Bounded(0, 253) align=Aligned(2) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting

struct sized_option size=1..254 mutate=Shifting
  sized_option.length                    offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  sized_option.value                     offset=AbsoluteStatic(0x01) size=Bounded(0, 253) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
